/* Hisar Roket Takımı: sinematik tema + kaydırmayla ilerleyen fırlatma sahnesi
   Rampada → Ateşleme → Kalkış → Apoje   |   Gece: lacivert gök ve gezegenler   Gündüz: hafif bulutlu mavi gök
   Kullanım: sayfanın en sonunda, </body> etiketinden hemen önce  <script src="roket.js"></script>
   index.html'de tema + gökyüzü + fırlatma sahnesi, magaza.html'de tema + gökyüzü çalışır. */
(function () {
  'use strict';

  // Takım roketinin görseli (gerçek roket fotoğrafındaki süslemelerle, bordo-bakır metalik)
  const ROKET_GORSELI = 'data:image/webp;base64,';

  // ---- AYARLAR ----
  const AYAR = {
    uzunluk: 480,        // sahnenin kaydırma boyu (ekran yüksekliğinin yüzdesi). Büyürse hareket yavaşlar.
    apoje: 7800,         // göstergede ulaşılan hedef irtifa (m)
    yumusaklik: 0.09     // 0.05 = daha süzülerek, 0.2 = kaydırmayı daha sıkı takip eder
  };

  // Sahne metinleri. aralik: kaydırmanın hangi bölümünde görüneceği (0 = baş, 1 = son)
  const SAHNELER = [
    { aralik: [0.14, 0.30], etiket: ['T-10', 'T-10'],
      baslik: ['Rampada', 'On the pad'],
      metin: ['Motor hariç tüm mekanik tasarımı özgün olarak geliştirdik.',
              'We developed all of the mechanical design ourselves, except the motor.'] },
    { aralik: [0.32, 0.46], etiket: ['T-0', 'T-0'],
      baslik: ['Ateşleme', 'Ignition'],
      metin: ['Aviyonik uçuş kartı ve yazılım da kendi geliştirmemiz.',
              'The avionics flight board and software are our own work too.'] },
    { aralik: [0.50, 0.74], etiket: ['T+', 'T+'],
      baslik: ['Kalkış', 'Liftoff'],
      metin: ['TEKNOFEST Orta İrtifa Roket Yarışması finalisti olduk.',
              'We were finalists in the TEKNOFEST Medium Altitude Rocket Competition.'] },
    { aralik: [0.80, 1.20], etiket: ['HEDEF APOJE', 'TARGET APOGEE'],
      baslik: ['7.800 metre', '7,800 meters'],
      metin: ['Yüksek irtifa roket projemizde hedefimiz bu. Bu yolculukta logonuz roketimizde yer alsın.',
              'That is the target of our high altitude rocket project. Join the journey with your logo on our rocket.'],
      dugmeler: [['#paketler', 'btn-hot', 'Sponsor Ol', 'Become a Sponsor'],
                 ['#is-birligi', 'btn-line', 'Bize Ulaşın', 'Contact Us']] }
  ];
  const ASAMALAR = [
    [0.00, 'GERİ SAYIM', 'COUNTDOWN'],
    [0.28, 'ATEŞLEME', 'IGNITION'],
    [0.40, 'İTKİ', 'POWERED'],
    [0.72, 'SÜZÜLME', 'COASTING'],
    [0.90, 'APOJE', 'APOGEE']
  ];

  const kok = document.documentElement;
  const azHareket = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  const geceMi = () => kok.getAttribute('data-theme') !== 'light';
  const dilNo = () => (kok.lang === 'en' ? 1 : 0);
  const sinirla = v => Math.min(1, Math.max(0, v));
  const gecis = (a, b, v) => { const t = sinirla((v - a) / (b - a)); return t * t * (3 - 2 * t); };
  const ara = (a, b, t) => a + (b - a) * t;
  const PI2 = Math.PI * 2;

  // Her çizimde aynı yıldız ve dağ dizilimi için sabit tohumlu rastgele sayı
  function tohumlu(t) {
    return function () {
      t = (t + 0x6D2B79F5) | 0;
      let x = Math.imul(t ^ (t >>> 15), 1 | t);
      x ^= x + Math.imul(x ^ (x >>> 7), 61 | x);
      return ((x ^ (x >>> 14)) >>> 0) / 4294967296;
    };
  }
  function yeniTuval(g, y, olcek) {
    const t = document.createElement('canvas');
    const k = olcek || 1;
    t.width = Math.max(1, Math.ceil(g * k));
    t.height = Math.max(1, Math.ceil(y * k));
    const c = t.getContext('2d');
    c.scale(k, k);
    return [t, c];
  }
  function leke(c, x, y, r, renk, saydam) {
    const g = c.createRadialGradient(x, y, 0, x, y, r);
    g.addColorStop(0, `rgba(${renk},${saydam})`);
    g.addColorStop(1, `rgba(${renk},0)`);
    c.fillStyle = g;
    c.fillRect(x - r, y - r, r * 2, r * 2);
  }
  function dikeyRenk(c, y0, y1, duraklar) {
    const g = c.createLinearGradient(0, y0, 0, y1);
    duraklar.forEach(d => g.addColorStop(d[0], d[1]));
    return g;
  }
  function daire(c, x, y, r) { c.beginPath(); c.arc(x, y, r, 0, PI2); }

  /* =====================================================================
     1) RENK TEMASI (bordo-bakır metalik, gece lacivert, gündüz gök mavisi)
     ===================================================================== */
  const METAL = 'linear-gradient(115deg,#4a0d1c 0%,#7e1f30 28%,#ad5449 45%,#e3a890 51%,#a44540 58%,#6c1828 78%,#4a0d1c 100%)';
  const tema = document.createElement('style');
  tema.textContent = `
    :root[data-theme="dark"] { --bg:#070d21; --panel:rgba(18,29,66,0.66); --line:rgba(172,192,255,0.15); --ink:#f5f2f7; --mute:#a7b1d1;
      --hot:#df8f7c; --hot2:#ffd3c2; --ice:#9fd0ff; --field:#0d1736; --img-bg:#0c1531; --hrt-golge:rgba(0,0,10,0.55); }
    :root[data-theme="light"] { --bg:#eaf4fd; --panel:rgba(255,255,255,0.76); --line:rgba(24,56,96,0.14); --ink:#10203c; --mute:#43557a;
      --hot:#8a2335; --hot2:#ad4f43; --ice:#12598f; --field:#ffffff; --img-bg:#ffffff; --hrt-golge:rgba(30,60,100,0.16); }
    :root[data-theme="dark"] .top { background: rgba(7,13,33,0.74); }
    :root[data-theme="light"] .top { background: rgba(240,248,255,0.76); }
    body::before { display: none; }
    .wrap.store-head, .wrap.grid, .wrap.crumbs, .wrap.product { padding-left: 24px; padding-right: 24px; }
    body { transition: background-color .8s ease, color .4s ease; }

    #hrt-gok { position: fixed; inset: 0; z-index: -1; pointer-events: none; overflow: hidden; }
    #hrt-gok > div { position: absolute; inset: 0; opacity: 0; transition: opacity .9s ease; }
    :root[data-theme="dark"] #hrt-gok .gece, :root[data-theme="light"] #hrt-gok .gunduz { opacity: 1; }
    #hrt-gok canvas { position: absolute; left: 0; top: 0; }
    #hrt-gok .pirilti { position: absolute; width: 2px; height: 2px; border-radius: 50%; background: #eef3ff; box-shadow: 0 0 6px 1px rgba(190,210,255,.8); animation: hrt-pirpir 4s ease-in-out infinite; }
    #hrt-gok .kayan { position: absolute; width: 130px; height: 1px; opacity: 0; background: linear-gradient(90deg, transparent, #fff); transform: rotate(24deg); animation: hrt-kayan 11s linear infinite; }
    #hrt-gok .bulut { position: absolute; left: 0; background-size: 100% 100%; animation: hrt-suzul linear infinite; }
    @keyframes hrt-pirpir { 0%,100% { opacity: .15 } 50% { opacity: .95 } }
    @keyframes hrt-kayan { 0% { opacity: 0; translate: 0 0 } 2% { opacity: .9 } 9% { opacity: 0; translate: 340px 150px } 100% { opacity: 0; translate: 340px 150px } }
    @keyframes hrt-suzul { from { translate: -60vw 0 } to { translate: 110vw 0 } }

    .btn-hot, .btn-hot:hover, a.order, a.order:hover, button.order, button.order:hover {
      color: #fff6f1; background: ${METAL}; background-size: 230% 100%; text-shadow: 0 1px 3px rgba(45,0,10,.75);
      animation: hrt-parilti 5.5s ease-in-out infinite; transition: filter .25s ease; }
    .btn-hot:hover, a.order:hover, button.order:hover { filter: brightness(1.18) saturate(1.1); }
    .btn-line { background: var(--panel); }
    @keyframes hrt-parilti { 0%,100% { background-position: 100% 0 } 50% { background-position: 0 0 } }

    .hero h1 .hot { background-image: linear-gradient(100deg,#c26a59 0%,#e9a38c 30%,#fff0e8 45%,#d8826c 58%,#b9505a 100%); background-size: 240% 100%; animation: hrt-parilti 6s ease-in-out infinite; }
    :root[data-theme="light"] .hero h1 .hot { background-image: linear-gradient(100deg,#6b1226 0%,#97303a 32%,#d07e66 46%,#8e2837 60%,#5e0f22 100%); }
    .sec-head::after { background: linear-gradient(90deg, var(--hot), transparent 80%); opacity: .55; }
    .mission::before { background: ${METAL}; height: 4px; }
    .mission.next::before { background: linear-gradient(90deg, #5d86c9, #cfe6ff, #5d86c9); }
    .station:hover { background: rgba(185,90,90,0.13); }
    .mission, a.card { transition: transform .35s ease, box-shadow .35s ease, border-color .35s ease, opacity .8s ease, translate .8s ease; }
    .mission:hover, a.card:hover { transform: translateY(-6px); box-shadow: 0 22px 46px -22px rgba(150,46,66,.65); border-color: var(--hot); }

    .pkg { position: relative; transition: transform .35s ease, box-shadow .35s ease, opacity .8s ease, translate .8s ease; }
    .pkg::before { content: ""; position: absolute; left: 0; right: 0; top: 0; height: 4px; background: linear-gradient(90deg,#6d422e,#e2b08c,#6d422e); }
    .pkg:nth-child(2)::before { background: linear-gradient(90deg,#737d91,#f2f5fb,#737d91); }
    .pkg:nth-child(3)::before { background: linear-gradient(90deg,#8d6c22,#ffe9a3,#8d6c22); }
    .pkg:nth-child(3) { box-shadow: inset 0 0 70px rgba(232,196,98,0.12); }
    .pkg:hover { transform: translateY(-9px); z-index: 2; box-shadow: 0 26px 54px -20px rgba(150,46,66,.7); }

    .hrt-gizli { opacity: 0; translate: 0 34px; }
    .hrt-gizli.hrt-acik { opacity: 1; translate: 0 0; }
    .sec-head.hrt-gizli, .cards3.hrt-gizli, .stations.hrt-gizli, .goals.hrt-gizli, .carousel.hrt-gizli, .sponsors.hrt-gizli, form.hrt-gizli, .contact.hrt-gizli, section .lead.hrt-gizli { transition: opacity .8s ease, translate .8s ease; }

    @media (prefers-reduced-motion: reduce) {
      #hrt-gok .pirilti, #hrt-gok .bulut, .btn-hot, a.order, button.order, .hero h1 .hot { animation: none !important; }
      #hrt-gok .kayan { display: none; }
    }
    @media print { #hrt-gok { display: none; } .hrt-gizli { opacity: 1; translate: 0 0; } }
  `;
  document.head.appendChild(tema);

  /* ---------------- ortak gök cisimleri ---------------- */
  function halkaliGezegen(r) {
    const [t, c] = yeniTuval(r * 5.4, r * 3.6, 2);
    c.translate(r * 2.7, r * 1.8);
    leke(c, 0, 0, r * 1.75, '222,140,120', 0.22);
    c.rotate(-0.32);
    const halka = (bas, son) => {
      for (let k = 1.36; k < 2.34; k += 0.028) {
        if (k > 1.9 && k < 1.99) continue;
        const a = 0.16 + 0.42 * Math.abs(Math.sin(k * 17)) * (k > 2.2 ? 0.5 : 1);
        c.strokeStyle = `rgba(${k < 1.9 ? '244,214,190' : '205,184,214'},${a})`;
        c.lineWidth = r * 0.03;
        c.beginPath(); c.ellipse(0, 0, r * k, r * k * 0.27, 0, bas, son); c.stroke();
      }
    };
    halka(Math.PI, PI2);
    c.save();
    daire(c, 0, 0, r); c.clip();
    let g = c.createRadialGradient(-r * 0.45, -r * 0.45, r * 0.05, 0, 0, r * 1.15);
    g.addColorStop(0, '#ffe0c9'); g.addColorStop(0.35, '#c97f6c'); g.addColorStop(0.72, '#7a2c42'); g.addColorStop(1, '#2a0d27');
    c.fillStyle = g; c.fillRect(-r, -r, r * 2, r * 2);
    [[-0.62, 0.1, 0.2], [-0.34, 0.07, -0.22], [-0.1, 0.14, 0.17], [0.2, 0.08, -0.25], [0.42, 0.13, 0.13], [0.7, 0.09, -0.2]].forEach(b => {
      c.fillStyle = b[2] > 0 ? `rgba(255,224,204,${b[2]})` : `rgba(55,8,34,${-b[2]})`;
      c.beginPath(); c.ellipse(0, r * b[0], r * 1.2, r * b[1], 0.02, 0, PI2); c.fill();
    });
    g = c.createRadialGradient(-r * 0.55, -r * 0.5, r * 0.5, -r * 0.2, -r * 0.15, r * 1.65);
    g.addColorStop(0, 'rgba(4,6,24,0)'); g.addColorStop(1, 'rgba(4,6,24,0.92)');
    c.fillStyle = g; c.fillRect(-r, -r, r * 2, r * 2);
    c.strokeStyle = 'rgba(20,4,24,0.45)'; c.lineWidth = r * 0.1;
    c.beginPath(); c.ellipse(0, r * 0.05, r * 1.5, r * 0.33, 0, 0, Math.PI); c.stroke();
    c.restore();
    halka(0, Math.PI);
    return t;
  }
  function kureGezegen(r, renkler, haleRengi, ayrinti) {
    const [t, c] = yeniTuval(r * 4.4, r * 4.4, 2);
    const m = r * 2.2;
    c.translate(m, m);
    leke(c, 0, 0, r * 2.15, haleRengi, 0.26);
    c.save();
    daire(c, 0, 0, r); c.clip();
    let g = c.createRadialGradient(-r * 0.4, -r * 0.42, r * 0.05, 0, 0, r * 1.2);
    renkler.forEach((k, i) => g.addColorStop(i / (renkler.length - 1), k));
    c.fillStyle = g; c.fillRect(-r, -r, r * 2, r * 2);
    if (ayrinti) ayrinti(c, r);
    g = c.createRadialGradient(-r * 0.5, -r * 0.5, r * 0.6, -r * 0.25, -r * 0.2, r * 1.7);
    g.addColorStop(0, 'rgba(5,8,28,0)'); g.addColorStop(1, 'rgba(5,8,28,0.9)');
    c.fillStyle = g; c.fillRect(-r, -r, r * 2, r * 2);
    c.restore();
    return t;
  }
  const ayYap = r => kureGezegen(r, ['#fffdf4', '#d9dae4', '#9ea4c0', '#59608a'], '200,214,255', (c, R) => {
    const rs = tohumlu(11);
    for (let i = 0; i < 9; i++) leke(c, (rs() - 0.5) * R * 1.5, (rs() - 0.5) * R * 1.5, R * (0.18 + rs() * 0.3), '86,92,130', 0.38);
    for (let i = 0; i < 26; i++) {
      const x = (rs() - 0.5) * R * 1.8, y = (rs() - 0.5) * R * 1.8, k = R * (0.025 + rs() * rs() * 0.13);
      c.fillStyle = 'rgba(80,84,118,0.34)'; daire(c, x, y, k); c.fill();
      c.strokeStyle = 'rgba(255,255,250,0.42)'; c.lineWidth = Math.max(0.5, k * 0.18);
      c.beginPath(); c.arc(x, y, k, 0.1, Math.PI * 0.95); c.stroke();
    }
  });
  const maviGezegen = r => kureGezegen(r, ['#d8f1ff', '#4f97e0', '#1d4896', '#0a1848'], '110,180,255', (c, R) => {
    c.strokeStyle = 'rgba(240,250,255,0.42)';
    [[-0.45, 0.16], [-0.05, 0.1], [0.38, 0.13]].forEach(b => {
      c.lineWidth = R * b[1];
      c.beginPath(); c.moveTo(-R, R * b[0]); c.bezierCurveTo(-R * 0.3, R * (b[0] - 0.25), R * 0.2, R * (b[0] + 0.22), R, R * (b[0] - 0.05)); c.stroke();
    });
  });
  const bakirGezegen = r => kureGezegen(r, ['#ffd9c4', '#b45a51', '#5e1a30', '#210a1c'], '230,130,110');

  function bulutYap(tohum) {
    const rs = tohumlu(tohum);
    const [t, c] = yeniTuval(600, 240);
    for (let i = 0; i < 80; i++) {
      const u = rs() * 2 - 1;
      const x = 300 + u * 215;
      const kabar = (1 - u * u) * 62;
      const y = 160 - rs() * kabar;
      const r = 24 + rs() * 42 * (1 - Math.abs(u) * 0.55);
      leke(c, x, y, r, '255,255,255', 0.34);
    }
    for (let i = 0; i < 22; i++) leke(c, 120 + rs() * 360, 168 + rs() * 12, 26 + rs() * 22, '196,216,238', 0.2);
    return t;
  }
  function nebulaCiz(c, g, y, rs) {
    // eğik samanyolu kuşağı
    for (let i = 0; i < 70; i++) {
      const t = rs(), x = t * g * 1.1 - g * 0.05, yy = y * (0.72 - t * 0.62) + (rs() - 0.5) * y * 0.2;
      const renk = ['96,118,220', '128,86,190', '160,70,120', '70,140,210'][(rs() * 4) | 0];
      leke(c, x, yy, y * (0.07 + rs() * 0.14), renk, 0.05 + rs() * 0.045);
    }
    for (let i = 0; i < g * y / 1100; i++) {
      const t = rs(), s = (rs() + rs() + rs()) / 3 - 0.5;
      c.fillStyle = `rgba(214,224,255,${0.12 + rs() * 0.5})`;
      c.fillRect(t * g, y * (0.72 - t * 0.62) + s * y * 0.34, rs() * 1.2 + 0.3, rs() * 1.2 + 0.3);
    }
  }

  /* =====================================================================
     2) TÜM SAYFANIN ARKASINDAKİ GÖKYÜZÜ
     ===================================================================== */
  (function sayfaGokyuzu() {
    const gok = document.createElement('div');
    gok.id = 'hrt-gok';
    gok.setAttribute('aria-hidden', 'true');
    gok.innerHTML = '<div class="gece"><canvas></canvas></div><div class="gunduz"><canvas></canvas></div>';
    document.body.prepend(gok);
    const [gece, gunduz] = gok.children;

    const rs = tohumlu(5);
    for (let i = 0; i < 34; i++) {
      const s = document.createElement('span');
      s.className = 'pirilti';
      s.style.cssText = `left:${rs() * 100}%;top:${rs() * 100}%;animation-delay:${-rs() * 6}s;animation-duration:${3 + rs() * 4}s;scale:${0.6 + rs() * 0.8}`;
      gece.appendChild(s);
    }
    [[12, 18, 2], [58, 8, 7.5]].forEach(k => {
      const s = document.createElement('span');
      s.className = 'kayan';
      s.style.cssText = `left:${k[0]}%;top:${k[1]}%;animation-delay:${k[2]}s`;
      gece.appendChild(s);
    });
    const bulutlar = [bulutYap(3).toDataURL(), bulutYap(9).toDataURL()];
    [[8, 460, 190, 0.5], [30, 300, 150, 0.4], [55, 520, 230, 0.42], [76, 340, 170, 0.5], [90, 420, 210, 0.38]].forEach((b, i) => {
      const d = document.createElement('div');
      d.className = 'bulut';
      d.style.cssText = `top:${b[0]}%;width:${b[1]}px;height:${b[1] * 0.4}px;opacity:${b[3]};background-image:url(${bulutlar[i % 2]});animation-duration:${b[2]}s;animation-delay:${-b[2] * ((i * 0.23 + 0.12) % 1)}s`;
      gunduz.appendChild(d);
    });

    let eskiG = 0, eskiY = 0;
    function ciz() {
      const g = window.innerWidth, y = window.innerHeight;
      if (g === eskiG && y <= eskiY) return;      // telefonda adres çubuğu oynayınca yeniden çizme
      eskiG = g; eskiY = y + 90;
      const k = Math.min(window.devicePixelRatio || 1, 2);
      const hazirla = kutu => {
        const t = kutu.querySelector('canvas');
        t.width = g * k; t.height = eskiY * k;
        t.style.width = g + 'px'; t.style.height = eskiY + 'px';
        const c = t.getContext('2d');
        c.setTransform(k, 0, 0, k, 0, 0);
        return c;
      };
      const r = tohumlu(21);
      let c = hazirla(gece);
      c.fillStyle = dikeyRenk(c, 0, eskiY, [[0, '#050a1f'], [0.55, '#09122f'], [1, '#0b1030']]);
      c.fillRect(0, 0, g, eskiY);
      c.globalAlpha = 0.6; nebulaCiz(c, g, eskiY, r); c.globalAlpha = 1;
      leke(c, g * 0.1, eskiY * 0.95, eskiY * 0.55, '110,34,70', 0.2);
      for (let i = 0; i < g * eskiY / 3600; i++) {
        c.fillStyle = `rgba(222,230,255,${0.15 + r() * 0.6})`;
        daire(c, r() * g, r() * eskiY, 0.3 + r() * r() * 1.1); c.fill();
      }
      const dar = g <= 900;
      c.globalAlpha = 0.5;
      const h = halkaliGezegen(dar ? 20 : 34);
      c.drawImage(h, g * 0.94 - h.width / 4, eskiY * 0.2 - h.height / 4, h.width / 2, h.height / 2);
      const m = maviGezegen(dar ? 8 : 13);
      c.drawImage(m, g * 0.045 - m.width / 4, eskiY * 0.68 - m.height / 4, m.width / 2, m.height / 2);
      c.globalAlpha = 1;

      c = hazirla(gunduz);
      c.fillStyle = dikeyRenk(c, 0, eskiY, [[0, '#cfe6fb'], [0.55, '#e6f2fd'], [1, '#f5f9fd']]);
      c.fillRect(0, 0, g, eskiY);
      leke(c, g * 0.92, eskiY * 0.06, eskiY * 0.5, '255,244,220', 0.65);
    }
    ciz();
    window.addEventListener('resize', ciz);
  })();

  /* =====================================================================
     3) BÖLÜMLERİN YUMUŞAK BELİRMESİ
     ===================================================================== */
  if (!azHareket && 'IntersectionObserver' in window) {
    const izle = new IntersectionObserver(girdiler => girdiler.forEach(g => {
      if (g.isIntersecting) { g.target.classList.add('hrt-acik'); izle.unobserve(g.target); }
    }), { threshold: 0.08 });
    document.querySelectorAll('section .sec-head, section .lead, .cards3, .stations, .mission, .goals, .carousel, .sponsors, .pkg, form.sponsor, .contact')
      .forEach(el => { el.classList.add('hrt-gizli'); izle.observe(el); });
  }

  /* =====================================================================
     4) FIRLATMA SAHNESİ (yalnızca ana sayfa)
     ===================================================================== */
  const hero = document.querySelector('.hero');
  if (!hero) return;

  const stil = document.createElement('style');
  stil.textContent = `
    #hrt-sahne { position: relative; z-index: 1; height: ${AYAR.uzunluk}vh; color: var(--ink); }
    .hrt-ekran { position: sticky; top: 0; height: 100vh; height: 100svh; min-height: 560px; overflow: hidden; background: var(--bg); }
    .hrt-ekran canvas { position: absolute; inset: 0; width: 100%; height: 100%; display: block; }
    .hrt-katman { position: absolute; inset: 0; max-width: 1180px; margin: 0 auto; padding: 0 24px; }
    .hrt-katman > .hero { position: absolute; inset: 0 24px; display: flex; align-items: center; min-height: 0; padding: 60px 0 0; }
    .hrt-katman > .hero > div:first-child { max-width: 600px; }
    .hrt-katman > .hero > div:first-child > * { animation-name: hrt-gir; animation-duration: 1.1s; animation-fill-mode: backwards; animation-timing-function: cubic-bezier(.2,.7,.2,1); }
    .hrt-katman > .hero > div:first-child > :nth-child(2) { animation-delay: .12s; }
    .hrt-katman > .hero > div:first-child > :nth-child(3) { animation-delay: .26s; }
    .hrt-katman > .hero > div:first-child > :nth-child(4) { animation-delay: .4s; }
    @keyframes hrt-gir { from { opacity: 0; translate: 0 30px } }
    .hrt-katman .hero-art { display: none; }
    .hrt-katman .mono { color: var(--mute); }
    .hrt-yazi { position: absolute; left: 24px; top: 50%; max-width: 500px; transform: translateY(-50%); opacity: 0; visibility: hidden; }
    .hrt-yazi .mono { color: var(--hot); font-weight: 600; }
    .hrt-yazi h2 { font-size: clamp(2.9rem, 6.4vw, 5rem); line-height: 0.95; margin: 10px 0 16px; text-shadow: 0 4px 26px var(--hrt-golge); }
    .hrt-yazi p { color: var(--ink); opacity: .86; font-size: 1.08rem; margin-bottom: 24px; }
    .hrt-gosterge { position: absolute; right: 22px; bottom: 26px; width: 262px; display: grid; grid-template-columns: 1.15fr 1fr; gap: 10px 14px;
      padding: 16px 18px 13px; border-radius: 16px; background: var(--panel); border: 1px solid var(--line); box-shadow: 0 18px 40px -22px var(--hrt-golge); }
    .hrt-gosterge > div:not(.hrt-cubuk) { border-left: 2px solid var(--hot); padding-left: 10px; }
    .hrt-gosterge b { display: block; font: 600 1.12rem "JetBrains Mono", ui-monospace, monospace; font-variant-numeric: tabular-nums; }
    .hrt-gosterge .mono { font-size: 0.6rem; }
    .hrt-cubuk { grid-column: 1 / -1; height: 3px; border-radius: 3px; overflow: hidden; background: var(--line); }
    .hrt-cubuk i { display: block; height: 100%; background: linear-gradient(90deg,#7e1f30,#c9705c,#ffd9c8); transform-origin: 0 50%; transform: scaleX(0); }
    .hrt-ipucu { position: absolute; left: 24px; bottom: 26px; white-space: nowrap; font-size: 0.64rem; }
    .hrt-ipucu span { display: inline-block; animation: hrt-zipla 1.7s ease-in-out infinite; }
    @keyframes hrt-zipla { 50% { translate: 0 5px } }

    @media (max-width: 900px) {
      .hrt-katman > .hero { align-items: flex-end; padding: 0 0 146px; }
      .hrt-katman .hero .mono { display: none; }
      .hrt-katman .hero h1 { font-size: clamp(2.5rem, 11vw, 4rem); margin: 10px 0 12px; }
      .hrt-katman .hero p.lead { font-size: 0.95rem; margin-bottom: 18px; }
      .hrt-katman .btns { gap: 8px; flex-wrap: nowrap; }
      .hrt-katman .btn { font-size: 1.05rem; padding: 10px 18px; white-space: nowrap; }
      .hrt-yazi { top: auto; bottom: 146px; right: 24px; transform: none; }
      .hrt-yazi p { font-size: 0.98rem; margin-bottom: 16px; }
      .hrt-gosterge { left: 24px; right: 24px; width: auto; bottom: 32px; padding: 11px 14px 9px; gap: 7px 12px; }
      .hrt-ipucu { left: 50%; transform: translateX(-50%); bottom: 10px; }
    }
    ${azHareket ? '#hrt-sahne { height: auto; } .hrt-ekran { position: relative; } .hrt-gosterge, .hrt-ipucu { display: none; } .hrt-katman > .hero > div:first-child > * { animation: none; }' : ''}
  `;
  document.head.appendChild(stil);

  const sahne = document.createElement('div');
  sahne.id = 'hrt-sahne';
  sahne.innerHTML = `
    <div class="hrt-ekran">
      <canvas aria-hidden="true"></canvas>
      <div class="hrt-katman">
        ${SAHNELER.map(s => `<div class="hrt-yazi"><div class="mono i18n"></div><h2 class="display i18n"></h2><p class="i18n"></p>${
          s.dugmeler ? `<div class="btns">${s.dugmeler.map(d => `<a class="btn ${d[1]} i18n" href="${d[0]}" data-tr="${d[2]}" data-en="${d[3]}"></a>`).join('')}</div>` : ''}</div>`).join('')}
        <div class="hrt-ipucu mono"><b class="i18n" data-tr="Fırlatmak için kaydır" data-en="Scroll to launch"></b> <span>↓</span></div>
      </div>
        <div class="hrt-gosterge">
          <div><span class="mono i18n" data-tr="İrtifa" data-en="Altitude"></span><b data-k="irtifa">0 M</b></div>
          <div><span class="mono i18n" data-tr="Aşama" data-en="Phase"></span><b data-k="asama"></b></div>
          <div class="hrt-cubuk"><i></i></div>
          <span class="mono i18n" data-tr="Temsili animasyon" data-en="Illustrative animation" style="grid-column:1/-1"></span>
        </div>
    </div>`;

  const eskiKap = hero.parentElement;             // #hero (içinde alttaki bilgi şeridi kalır)
  eskiKap.before(sahne);
  eskiKap.removeAttribute('id');
  const capa = document.createElement('span');    // logo bağlantısı (#hero) çalışmaya devam etsin
  capa.id = 'hero';
  sahne.before(capa);
  const katman = sahne.querySelector('.hrt-katman');
  katman.prepend(hero);

  const yazilar = [...katman.querySelectorAll('.hrt-yazi')];
  yazilar.forEach((el, i) => {
    const s = SAHNELER[i];
    [['.mono', s.etiket], ['h2', s.baslik], ['p', s.metin]].forEach(([sec, t]) => {
      const h = el.querySelector(sec);
      h.dataset.tr = t[0];
      h.dataset.en = t[1];
    });
  });
  const dilUygula = () => {
    const d = dilNo() ? 'en' : 'tr';
    sahne.querySelectorAll('.i18n').forEach(el => { if (el.dataset[d] !== undefined) el.textContent = el.dataset[d]; });
  };
  dilUygula();

  const ekran = sahne.querySelector('.hrt-ekran');
  const tuval = sahne.querySelector('canvas');
  const c = tuval.getContext('2d');
  const gIrtifa = sahne.querySelector('[data-k="irtifa"]');
  const gAsama = sahne.querySelector('[data-k="asama"]');
  const cubuk = sahne.querySelector('.hrt-cubuk i');
  const ipucu = sahne.querySelector('.hrt-ipucu');

  // Sahne, yapışkan üst menünün arkasından başlasın
  const ustMenu = document.getElementById('topbar');
  const geriSayim = document.getElementById('countdown');
  function menuHizala() {
    sahne.style.marginTop = ustMenu && (!geriSayim || geriSayim.hidden) ? -ustMenu.offsetHeight + 'px' : '0';
  }

  let G = 0, Y = 0, dpr = 1, dar = false, L = 0, zy = 0, ufuk = 0, rx = 0;
  let yildizKat, nebulaKat, parlaklar = [], isiklar = [], daglar = [], bulutlar = [], gezegenler = [], hizCizgileri = [];
  let dumanlar = [], kayanlar = [];
  const bulutResimleri = [bulutYap(2), bulutYap(17), bulutYap(31)];

  function dumanSprite(ic, dis) {
    const [t, d] = yeniTuval(128, 128);
    const g = d.createRadialGradient(64, 64, 0, 64, 64, 64);
    g.addColorStop(0, `rgba(${ic},0.62)`);
    g.addColorStop(0.55, `rgba(${dis},0.3)`);
    g.addColorStop(1, `rgba(${dis},0)`);
    d.fillStyle = g;
    d.fillRect(0, 0, 128, 128);
    return t;
  }
  const dumanGece = dumanSprite('186,192,222', '118,122,160');
  const dumanGunduz = dumanSprite('255,255,255', '206,208,214');
  const dumanSicak = dumanSprite('255,212,170', '206,106,84');

  // Takım roketi: parlama efektleri için ayrı bir katmanda boyanır
  const roketResmi = new Image();
  const [roketKat] = yeniTuval(2, 2);
  const rk = roketKat.getContext('2d');
  roketResmi.onload = () => uyandir();
  roketResmi.src = ROKET_GORSELI;

  function olc() {
    menuHizala();
    const yeniG = ekran.clientWidth, yeniY = ekran.clientHeight;
    const yeniDpr = Math.min(window.devicePixelRatio || 1, 2);
    if (yeniG === G && yeniY === Y && yeniDpr === dpr) return;
    G = yeniG; Y = yeniY; dpr = yeniDpr;
    dar = G <= 900;
    tuval.width = G * dpr;
    tuval.height = Y * dpr;
    c.setTransform(dpr, 0, 0, dpr, 0, 0);

    L = Y * (dar ? 0.31 : 0.71);
    rx = G * (dar ? 0.68 : 0.70);
    zy = Y * (dar ? 0.42 : 0.87);                 // rampanın bastığı çizgi
    ufuk = zy - Y * (dar ? 0.035 : 0.075);

    roketKat.width = Math.ceil(L * 102 / 975 * 1.18 * dpr);
    roketKat.height = Math.ceil(L * 979 / 975 * dpr);

    const r = tohumlu(77);
    let t;
    [yildizKat, t] = yeniTuval(G, Y, dpr);
    for (let i = 0; i < G * Y / 2100; i++) {
      t.fillStyle = `rgba(${r() < 0.18 ? '255,222,206' : '214,228,255'},${0.18 + r() * 0.7})`;
      daire(t, r() * G, r() * Y, 0.25 + r() * r() * 1.05); t.fill();
    }
    [nebulaKat, t] = yeniTuval(G, Y * 1.2, 1);
    nebulaCiz(t, G, Y * 1.1, r);

    parlaklar = Array.from({ length: Math.round(G * Y / 17000) }, () => ({
      x: r() * G, y: r() * Y, r: 0.8 + r() * 1.1, d: 0.4 + r() * 0.8, faz: r() * PI2, hiz: 0.0012 + r() * 0.0026, isin: r() < 0.14
    }));
    hizCizgileri = Array.from({ length: dar ? 24 : 46 }, () => ({ x: r() * G, y: r() * Y, d: 0.5 + r() }));

    const sirt = (taban, yukseklik, tohum) => {
      const q = tohumlu(tohum), f = [q() * 6, q() * 6, q() * 6, q() * 6], n = [];
      for (let x = -10; x <= G + 18; x += 8) {
        const u = x / (dar ? 150 : 300);
        const h = 0.48 + 0.28 * Math.sin(u * 1.3 + f[0]) + 0.16 * Math.sin(u * 3.1 + f[1]) + 0.06 * Math.sin(u * 7.9 + f[2]) + 0.025 * Math.sin(u * 19 + f[3]);
        n.push([x, taban - Math.max(0.05, h) * yukseklik]);
      }
      return n;
    };
    daglar = [sirt(ufuk, Y * 0.15, 4), sirt(ufuk + Y * 0.004, Y * 0.092, 8), sirt(ufuk + Y * 0.012, Y * 0.045, 15)];
    isiklar = Array.from({ length: dar ? 26 : 60 }, () => ({ x: r() * G, y: ufuk + Y * 0.008 + r() * r() * Y * 0.07, faz: r() * PI2, sicak: r() < 0.6 }));

    bulutlar = (dar
      ? [[0.10, 0.17, 0.62, 0.7], [0.92, 0.27, 0.55, 0.55], [0.40, 0.06, 0.45, 0.45], [0.75, 0.50, 0.7, 0.4], [0.15, 0.65, 0.6, 0.35]]
      : [[0.10, 0.17, 0.27, 0.72], [0.47, 0.11, 0.2, 0.5], [0.88, 0.27, 0.31, 0.7], [0.57, 0.50, 0.22, 0.45], [0.27, 0.65, 0.3, 0.32], [0.97, 0.60, 0.2, 0.5], [0.70, 0.05, 0.17, 0.4]]
    ).map((b, i) => ({ x: b[0] * G, y: b[1] * Y, g: b[2] * G, a: b[3], d: 0.35 + (i % 3) * 0.28, v: 0.045 + (i % 4) * 0.018, s: i % 3 }));

    const kucuk = Y * (dar ? 0.62 : 1);
    gezegenler = (dar
      ? [[ayYap(kucuk * 0.04), 0.30, 0.165, 0.07], [halkaliGezegen(kucuk * 0.044), 0.15, 0.31, 0.12], [maviGezegen(kucuk * 0.019), 0.91, 0.19, 0.16]]
      : [[ayYap(kucuk * 0.043), 0.47, 0.172, 0.05], [halkaliGezegen(kucuk * 0.056), 0.912, 0.172, 0.028], [maviGezegen(kucuk * 0.019), 0.565, 0.41, 0.17], [bakirGezegen(kucuk * 0.011), 0.955, 0.55, 0.24]]
    ).map(g => ({ t: g[0], x: g[1], y: g[2], d: g[3] }));

    dumanlar = [];
    uyandir();
  }

  /* ---------------- gökyüzü ---------------- */
  function geceGogu(a, s) {
    c.globalAlpha = a;
    c.fillStyle = dikeyRenk(c, 0, Y, [[0, '#030718'], [0.38, '#08123a'], [0.68, '#14225a'], [1, '#101a45']]);
    c.fillRect(0, 0, G, Y);
    c.drawImage(nebulaKat, 0, -Y * 0.16 + s.ucus * Y * 0.13, G, Y * 1.2);
    // ufuk ışıması
    const ufukA = (1 - s.kalkis) * a;
    if (ufukA > 0.01) {
      c.globalAlpha = ufukA;
      c.save(); c.translate(rx, ufuk + s.dunya); c.scale(2.4, 0.62);
      leke(c, 0, 0, Y * 0.42, '146,58,104', 0.42);
      leke(c, 0, 0, Y * 0.2, '214,122,118', 0.3);
      c.restore();
    }
    c.globalAlpha = a;
    const oy = (s.kayma * 0.16) % Y;
    c.drawImage(yildizKat, 0, oy - Y, G, Y);
    c.drawImage(yildizKat, 0, oy, G, Y);
    for (const y of parlaklar) {
      const yy = (y.y + s.kayma * y.d * 0.5) % Y;
      const k = 0.55 + 0.45 * Math.sin(s.zaman * y.hiz + y.faz);
      c.globalAlpha = a * (0.3 + 0.7 * k);
      c.fillStyle = '#eef3ff';
      if (s.hiz > 0.05) { c.globalAlpha *= 1 - s.hiz * 0.45; c.fillRect(y.x, yy, y.r * 0.75, y.r + s.hiz * y.d * 22); }
      else { daire(c, y.x, yy, y.r * (0.8 + k * 0.3)); c.fill(); }
      if (y.isin && s.hiz < 0.3) {
        const u = y.r * (4 + k * 6);
        c.globalAlpha = a * k * 0.7;
        c.fillRect(y.x - u, yy - 0.4, u * 2, 0.8);
        c.fillRect(y.x - 0.4, yy - u, 0.8, u * 2);
        leke(c, y.x, yy, u * 0.8, '180,200,255', 0.35);
      }
    }
    c.globalAlpha = a;
    gezegenler.forEach((g, i) => {
      const w = g.t.width / 2, h = g.t.height / 2;
      const sal = Math.sin(s.zaman / 2600 + i * 2) * 3;
      c.drawImage(g.t, g.x * G - w / 2, g.y * Y - h / 2 + s.ucus * Y * g.d + sal, w, h);
    });
    // kayan yıldız
    if (!azHareket && Math.random() < 0.006 * s.dt) {
      kayanlar.push({ x: G * (0.15 + Math.random() * 0.8), y: Y * Math.random() * 0.4, omur: 1 });
    }
    kayanlar = kayanlar.filter(k => k.omur > 0);
    for (const k of kayanlar) {
      k.omur -= 0.022 * s.dt; k.x -= 9 * s.dt; k.y += 4.2 * s.dt;
      const g = c.createLinearGradient(k.x, k.y, k.x + 110, k.y - 51);
      g.addColorStop(0, `rgba(255,255,255,${Math.max(0, k.omur)})`);
      g.addColorStop(1, 'rgba(160,190,255,0)');
      c.strokeStyle = g; c.lineWidth = 1.6;
      c.beginPath(); c.moveTo(k.x, k.y); c.lineTo(k.x + 110, k.y - 51); c.stroke();
    }
    c.globalAlpha = 1;
  }

  function gunduzGogu(a, s) {
    c.globalAlpha = a;
    c.fillStyle = dikeyRenk(c, 0, Y, [[0, '#6ea9e4'], [0.42, '#9ec9f1'], [0.72, '#d3e9fb'], [1, '#eef6fd']]);
    c.fillRect(0, 0, G, Y);
    if (s.ucus > 0.01) {                                // yükseldikçe gök koyulaşır
      c.globalAlpha = a * s.ucus * 0.75;
      c.fillStyle = dikeyRenk(c, 0, Y, [[0, '#23579f'], [0.55, 'rgba(70,130,205,0.35)'], [1, 'rgba(120,180,235,0)']]);
      c.fillRect(0, 0, G, Y);
    }
    c.globalAlpha = a;
    leke(c, G * 0.92, Y * 0.13, Y * 0.42, '255,246,222', 0.75);
    leke(c, G * 0.92, Y * 0.13, Y * 0.07, '255,253,244', 0.95);
    for (const b of bulutlar) {
      const h = b.g * 0.4;
      const dongu = G + b.g * 2;
      const x = ((b.x + s.zaman * b.v * 0.12 + b.g) % dongu) - b.g;
      const boy = Y + h * 2;
      const y = ((b.y + s.kayma * b.d * 0.75 + h) % boy) - h;
      c.globalAlpha = a * b.a;
      c.drawImage(bulutResimleri[b.s], x - b.g / 2, y - h / 2, b.g, h);
    }
    c.globalAlpha = 1;
  }

  function sirtCiz(n, renk, alt, kayma) {
    c.fillStyle = renk;
    c.beginPath();
    c.moveTo(-10, alt + kayma);
    n.forEach(q => c.lineTo(q[0], q[1] + kayma));
    c.lineTo(G + 18, alt + kayma);
    c.closePath();
    c.fill();
  }

  function zeminCiz(a, gece, s) {
    if (ufuk - Y * 0.16 + s.dunya * 0.7 > Y) return;
    c.globalAlpha = a;
    const renkler = gece ? ['#1c2960', '#131d49', '#0c1436'] : ['#a3bcd9', '#8ea6c2', '#a3a894'];
    sirtCiz(daglar[0], renkler[0], ufuk + 4, s.dunya * 0.72);
    sirtCiz(daglar[1], renkler[1], ufuk + 8, s.dunya * 0.86);
    const zk = ufuk + s.dunya;
    c.fillStyle = gece
      ? dikeyRenk(c, zk, zk + Y * 0.3, [[0, '#19224f'], [0.45, '#0d1334'], [1, '#070d21']])
      : dikeyRenk(c, zk, zk + Y * 0.3, [[0, '#c9c9b4'], [0.4, '#c6bda1'], [1, '#d8d6c8']]);
    c.fillRect(0, zk, G, Y);
    sirtCiz(daglar[2], renkler[2], ufuk + Y * 0.016, s.dunya);
    if (gece) {
      for (const i of isiklar) {
        c.globalAlpha = a * (0.35 + 0.4 * Math.sin(s.zaman * 0.002 + i.faz) ** 2);
        c.fillStyle = i.sicak ? '#ffd9ae' : '#bcd6ff';
        c.fillRect(i.x, i.y + s.dunya, 1.7, 1.4);
      }
    }
    c.globalAlpha = 1;
  }

  // Apojede aşağıda beliren dünya ufku
  function dunyaUfku(a, gece, e) {
    if (e < 0.01) return;
    const R = Math.max(G, Y) * 1.55;
    const tepe = Y * ara(1.14, dar ? 0.49 : 0.79, e);
    const mx = G * 0.56, my = tepe + R;
    c.globalAlpha = a * e;
    let g = c.createRadialGradient(mx, my, R - 3, mx, my, R + Y * 0.11);
    g.addColorStop(0, gece ? 'rgba(120,196,255,0.78)' : 'rgba(255,255,255,0.95)');
    g.addColorStop(0.22, gece ? 'rgba(70,130,240,0.34)' : 'rgba(200,232,255,0.5)');
    g.addColorStop(1, 'rgba(80,130,240,0)');
    c.fillStyle = g;
    daire(c, mx, my, R + Y * 0.11); c.fill();
    c.save();
    daire(c, mx, my, R); c.clip();
    c.fillStyle = gece
      ? dikeyRenk(c, tepe, Y, [[0, '#3f83cc'], [0.14, '#1c4c93'], [0.5, '#0b2257'], [1, '#07102c']])
      : dikeyRenk(c, tepe, Y, [[0, '#d5edff'], [0.18, '#83bbea'], [0.6, '#6ba0d3'], [1, '#c4dbee']]);
    c.fillRect(0, tepe - 4, G, Y - tepe + 8);
    const r = tohumlu(41);
    for (let i = 0; i < 46; i++) {
      const x = r() * G, y = tepe + 6 + r() * (Y - tepe), w = 24 + r() * 120;
      c.save(); c.translate(x, y + ((x - mx) * (x - mx)) / (2 * R)); c.scale(1, 0.14);
      leke(c, 0, 0, w, '236,246,255', gece ? 0.2 : 0.55);
      c.restore();
    }
    c.restore();
    c.globalAlpha = 1;
  }

  // Gece fırlatma alanını aydınlatan projektörler
  function projektorler(a, s) {
    const g = a * (1 - s.kalkis);
    if (g < 0.02) return;
    c.save();
    c.globalCompositeOperation = 'lighter';
    const taban = zy + L * 0.045 + s.dunya;
    [[rx - L * 0.62, 1], [rx + L * 0.46, -1]].forEach(([x, yon]) => {
      const hx = rx + yon * L * 0.06, hy = taban - L * 0.86;
      const aci = Math.atan2(hy - taban, hx - x), dx = -Math.sin(aci) * L * 0.2, dy = Math.cos(aci) * L * 0.2;
      for (let k = 1; k > 0.3; k -= 0.22) {
        const gr = c.createLinearGradient(x, taban, hx, hy);
        gr.addColorStop(0, `rgba(150,186,255,${0.11 * g})`);
        gr.addColorStop(1, 'rgba(150,186,255,0)');
        c.fillStyle = gr;
        c.beginPath(); c.moveTo(x, taban); c.lineTo(hx + dx * k, hy + dy * k); c.lineTo(hx - dx * k, hy - dy * k); c.closePath(); c.fill();
      }
      c.globalAlpha = g;
      leke(c, x, taban, L * 0.045, '206,226,255', 0.9);
      c.globalAlpha = 1;
    });
    c.restore();
  }

  // Fırlatma rampası
  function rampaCiz(s) {
    const taban = zy + s.dunya;
    if (taban - L * 1.5 > Y) return;
    const X = v => rx + v * L;
    const ust = taban - L * 0.07;
    const tepe = ust - L * 1.3;
    const gece = s.gece > 0.5;
    const cokgen = (renk, n) => {
      c.fillStyle = renk; c.beginPath();
      n.forEach((q, i) => c[i ? 'lineTo' : 'moveTo'](q[0], q[1]));
      c.closePath(); c.fill();
    };
    const kutu = (x, y, w, h, renk) => { c.fillStyle = renk; c.fillRect(x, y, w, h); };
    const metalDolgu = (x, w, a, b, d) => {
      const g = c.createLinearGradient(x, 0, x + w, 0);
      g.addColorStop(0, a); g.addColorStop(0.4, b); g.addColorStop(1, d);
      return g;
    };
    [-0.082, -0.050].forEach(v => {
      kutu(X(v), tepe, L * 0.025, ust - tepe, metalDolgu(X(v), L * 0.025, '#5b6478', gece ? '#aebbd8' : '#eef1f5', '#3d4558'));
      kutu(X(v + 0.016), tepe, L * 0.003, ust - tepe, '#2e3546');
    });
    cokgen(metalDolgu(X(-0.125), L * 0.051, gece ? '#59648a' : '#8b95a4', gece ? '#48526f' : '#737d8c', gece ? '#2c3450' : '#555e6d'),
      [[X(-0.125), ust], [X(-0.125), ust - L * 0.93], [X(-0.112), ust - L * 1.04], [X(-0.074), ust - L * 1.04], [X(-0.074), ust]]);
    c.fillStyle = '#242b3b';
    for (let i = 1; i < 14; i++) [-0.117, -0.082].forEach(v => c.fillRect(X(v), ust - i * L * 0.072, L * 0.004, L * 0.004));
    [0.04, 0.36, 0.69, 1.02].forEach(v => kutu(X(-0.077), ust - L * v, L * 0.052, L * 0.022, gece ? '#49536f' : '#646d7c'));
    c.lineCap = 'round';
    const cizgi = (x1, y1, x2, y2, w, renk) => {
      c.strokeStyle = renk; c.lineWidth = w; c.beginPath(); c.moveTo(x1, y1); c.lineTo(x2, y2); c.stroke();
    };
    cizgi(X(-0.19), ust, X(-0.125), ust - L * 0.45, L * 0.009, gece ? '#b9c6e4' : '#dfe4ea');
    cizgi(X(-0.22), ust + L * 0.02, X(-0.16), ust - L * 0.22, L * 0.026, gece ? '#4b5676' : '#6a7381');
    kutu(X(-0.36), ust + L * 0.018, L * 0.25, L * 0.075, gece ? '#343d58' : '#59626f');
    c.fillStyle = '#121725';
    [-0.31, -0.25, -0.19].forEach(v => { daire(c, X(v), ust + L * 0.056, L * 0.016); c.fill(); });
    cokgen(gece ? '#465070' : '#69727f', [[X(-0.17), taban + L * 0.05], [X(-0.12), ust], [X(0.035), ust], [X(0.06), taban + L * 0.05]]);
    cokgen(gece ? '#2a324c' : '#47505e', [[X(0.035), ust], [X(0.085), ust], [X(0.105), taban + L * 0.03], [X(0.06), taban + L * 0.05]]);
    kutu(X(-0.13), ust - L * 0.006, L * 0.23, L * 0.012, gece ? '#7784a8' : '#97a0ad');
    c.fillStyle = '#eef1f7';
    c.font = `700 ${L * 0.075}px Inter, sans-serif`;
    c.textAlign = 'center';
    c.fillText('1', X(-0.055), taban + L * 0.028);
    if (gece) {                                           // yanıp sönen kırmızı ikaz ışığı
      const y = 0.5 + 0.5 * Math.sin(s.zaman / 320);
      leke(c, X(-0.093), ust - L * 1.05, L * 0.03, '255,70,80', 0.25 + y * 0.7);
      kutu(X(-0.096), ust - L * 1.053, L * 0.006, L * 0.006, '#ffb0b4');
    }
  }

  // Alev: roketin yerel koordinatında, memeden aşağı doğru
  function alevCiz(boyut, alev, s) {
    if (alev <= 0.01) return;
    const w = boyut * 0.05, alt = boyut / 2 - boyut * 0.004;
    const titre = 1 + Math.sin(s.zaman / 37) * 0.06 + (Math.random() - 0.5) * 0.12;
    const boy = boyut * 0.5 * alev * titre;
    c.save();
    c.save(); c.translate(0, alt + boy * 0.22); c.scale(0.5, 1);
    leke(c, 0, 0, boyut * 0.28 * alev, '224,104,78', 0.46);
    c.restore();
    [[1.35, 1, '158,42,48', 0.7], [0.98, 0.8, '226,100,72', 0.92], [0.66, 0.6, '255,190,120', 0.97], [0.36, 0.42, '255,250,236', 1]].forEach(([en, b, renk, a]) => {
      const g = c.createLinearGradient(0, alt, 0, alt + boy * b);
      g.addColorStop(0, `rgba(${renk},${a})`);
      g.addColorStop(0.55, `rgba(${renk},${a * 0.72})`);
      g.addColorStop(1, `rgba(${renk},0)`);
      c.fillStyle = g;
      c.beginPath();
      c.moveTo(-w * 0.25 * en, alt);
      c.bezierCurveTo(-w * 0.95 * en, alt + boy * b * 0.25, -w * 0.3 * en, alt + boy * b * 0.65, 0, alt + boy * b);
      c.bezierCurveTo(w * 0.3 * en, alt + boy * b * 0.65, w * 0.95 * en, alt + boy * b * 0.25, w * 0.25 * en, alt);
      c.fill();
    });
    for (let i = 0; i < 4; i++) {                         // şok elmasları
      c.fillStyle = `rgba(255,255,252,${(0.85 - i * 0.19) * alev})`;
      c.beginPath(); c.ellipse(0, alt + boy * (0.07 + i * 0.085), w * (0.17 - i * 0.025), boy * 0.022, 0, 0, PI2); c.fill();
    }
    c.restore();
  }

  function roketCiz(boyut, alev, s) {
    alevCiz(boyut, alev, s);
    if (!roketResmi.complete || !roketResmi.naturalWidth) return;
    const w = roketKat.width, h = roketKat.height;
    rk.globalCompositeOperation = 'source-over';
    rk.clearRect(0, 0, w, h);
    rk.drawImage(roketResmi, 0, 0, w, h);
    rk.globalCompositeOperation = 'source-atop';
    const boya = (g) => { rk.fillStyle = g; rk.fillRect(0, 0, w, h); };
    let g;
    if (s.gece > 0.01) {                                  // gece: sağ kenarda mavi ay ışığı
      g = rk.createLinearGradient(0, 0, w, 0);
      g.addColorStop(0.55, 'rgba(110,150,255,0)'); g.addColorStop(0.72, `rgba(130,170,255,${0.34 * s.gece})`); g.addColorStop(1, `rgba(120,165,255,${0.3 * s.gece})`);
      boya(g);
    }
    if (alev > 0.02) {                                    // alevin gövdeye vuran ışığı
      g = rk.createLinearGradient(0, h * 0.6, 0, h);
      g.addColorStop(0, 'rgba(255,170,130,0)'); g.addColorStop(1, `rgba(255,178,136,${0.62 * alev})`);
      boya(g);
    }
    const tur = (s.zaman % 4600) / 4600;                  // gövde boyunca gezen parlama
    if (!azHareket && tur < 0.4) {
      const y = h * (1.15 - (tur / 0.4) * 1.3);
      g = rk.createLinearGradient(0, y - h * 0.055, w * 0.55, y + h * 0.055);
      g.addColorStop(0, 'rgba(255,238,228,0)'); g.addColorStop(0.5, 'rgba(255,244,236,0.8)'); g.addColorStop(1, 'rgba(255,238,228,0)');
      boya(g);
    }
    const o = boyut / 975;
    c.imageSmoothingQuality = 'high';
    c.drawImage(roketKat, -50 * o * 1.18, -boyut / 2 - 2 * o, 102 * o * 1.18, 979 * o);
    const pk = azHareket ? 0 : Math.max(0, Math.sin(s.zaman / 520)) ** 14;   // burunda yıldız parıltısı
    if (pk > 0.02) {
      const y = -boyut / 2 + boyut * 0.055, x = -boyut * 0.007, u = boyut * 0.034 * pk;
      c.save();
      c.globalCompositeOperation = 'lighter';
      leke(c, x, y, u * 0.7, '255,226,214', 0.85 * pk);
      c.fillStyle = `rgba(255,250,246,${pk})`;
      c.beginPath();
      c.moveTo(x - u, y); c.quadraticCurveTo(x, y, x, y - u); c.quadraticCurveTo(x, y, x + u, y);
      c.quadraticCurveTo(x, y, x, y + u); c.quadraticCurveTo(x, y, x - u, y);
      c.fill();
      c.restore();
    }
  }

  /* ---------------- animasyon ---------------- */
  let p = null, geceOran = null, kayma = 0, sonZaman = 0, kare = null, gorunur = true, sonAsama = '';

  function hedefOran() {
    if (azHareket) return 0;
    const yol = sahne.offsetHeight - Y;
    return yol > 0 ? sinirla(-sahne.getBoundingClientRect().top / yol) : 0;
  }

  function ciz(zaman) {
    kare = null;
    const dt = Math.min(3, sonZaman ? (zaman - sonZaman) / 16.67 : 1);
    sonZaman = zaman;
    const hedef = hedefOran();
    if (p === null) p = hedef;
    else p += (hedef - p) * Math.min(1, AYAR.yumusaklik * dt);
    if (Math.abs(hedef - p) < 0.0004) p = hedef;
    const hedefGece = geceMi() ? 1 : 0;                   // gece / gündüz yumuşak geçiş
    if (geceOran === null || azHareket) geceOran = hedefGece;
    else geceOran += (hedefGece - geceOran) * Math.min(1, 0.07 * dt);
    if (Math.abs(hedefGece - geceOran) < 0.01) geceOran = hedefGece;
    const gece = geceOran;

    const atesleme = gecis(0.27, 0.37, p);
    const sonme = 1 - gecis(0.70, 0.78, p);
    const alev = atesleme * sonme;
    const kalkis = gecis(0.39, 0.62, p);
    const ucus = sinirla((p - 0.39) / 0.61);
    const yatma = gecis(0.70, 0.98, p);
    const hiz = gecis(0.40, 0.58, p) * (1 - gecis(0.68, 0.92, p));
    const dunya = gecis(0.39, 0.66, p) * Y * 1.4;
    kayma += (hiz * 20) * dt;
    const s = { zaman: azHareket ? 0 : zaman, dt, gece, kalkis, ucus, hiz, dunya, kayma };

    const baslangicY = zy - L * 0.07 - L / 2;
    const sars = alev * (1 - kalkis * 0.8);
    const x = ara(rx, G * (dar ? 0.52 : 0.70), yatma) + Math.sin(zaman / 23) * sars * 1.5;
    const y = ara(ara(baslangicY, Y * (dar ? 0.30 : 0.46), kalkis), Y * (dar ? 0.29 : 0.355), yatma) + Math.sin(zaman / 31) * sars * 1.2;
    const aci = -(gecis(0.52, 0.72, p) * 0.2 + yatma * (Math.PI / 2 - 0.2));
    const boyut = L * ara(1, dar ? 0.9 : 0.76, yatma);

    c.clearRect(0, 0, G, Y);
    // gökyüzü ve manzara (geçiş sırasında iki katman üst üste)
    const apojeE = gecis(0.70, 0.97, p);
    if (gece < 1) { gunduzGogu(1, s); dunyaUfku(1, false, apojeE); zeminCiz(1, false, s); }
    if (gece > 0) { geceGogu(gece, s); dunyaUfku(gece, true, apojeE); zeminCiz(gece, true, s); }

    // hız çizgileri
    if (hiz > 0.08) {
      c.fillStyle = gece > 0.5 ? 'rgba(196,214,255,0.14)' : 'rgba(255,255,255,0.42)';
      for (const h of hizCizgileri) c.fillRect(h.x, (h.y + kayma * h.d * 1.5) % Y, 1, hiz * h.d * 38);
    }

    projektorler(gece, s);
    rampaCiz(s);

    // ateşlemede etrafı aydınlatan ışık patlaması
    const isik = alev * (1 - kalkis);
    if (isik > 0.02) {
      c.save();
      c.globalCompositeOperation = 'lighter';
      c.translate(rx, zy - L * 0.04); c.scale(1.7, 1);
      leke(c, 0, 0, L * 0.46, '218,108,86', (gece > 0.5 ? 0.46 : 0.2) * isik);
      leke(c, 0, 0, L * 0.17, '255,222,188', 0.6 * isik);
      c.restore();
    }

    // duman
    if (!azHareket && alev > 0.08) {
      const yerde = 1 - gecis(0.40, 0.52, p);
      const adet = Math.random() < alev ? (yerde > 0.5 ? 2 : 1) : 0;
      for (let i = 0; i < adet; i++) {
        const yer = Math.random() < yerde;
        const kuyruk = boyut * 0.62;
        dumanlar.push({
          x: yer ? rx : x - Math.sin(aci) * kuyruk,
          y: yer ? zy - L * 0.02 : y + Math.cos(aci) * kuyruk,
          vx: yer ? (Math.random() - 0.5) * L * 0.024 : (Math.random() - 0.5) * 1.2 - Math.sin(aci) * 5,
          vy: yer ? -Math.random() * 0.9 : 4 + Math.random() * 4,
          r: boyut * (yer ? 0.058 : 0.03) * (0.8 + Math.random() * 0.5), omur: 1, yer
        });
      }
    }
    const sinir = dar ? 80 : 120;
    if (dumanlar.length > sinir) dumanlar.splice(0, dumanlar.length - sinir);
    dumanlar = dumanlar.filter(d => (d.omur -= (d.yer ? 0.015 : 0.032) * dt) > 0);
    for (const d of dumanlar) {
      d.x += d.vx * dt; d.y += d.vy * dt;
      if (d.yer) d.vx *= Math.pow(0.975, dt);
      d.r += boyut * (d.yer ? 0.0023 : 0.0017) * dt;
      c.globalAlpha = d.omur * 0.85;
      c.drawImage(gece > 0.5 ? dumanGece : dumanGunduz, d.x - d.r, d.y - d.r, d.r * 2, d.r * 2);
      const sicak = sinirla((d.omur - 0.72) / 0.28) * alev;
      if (sicak > 0) {
        c.globalAlpha = sicak * (gece > 0.5 ? 0.9 : 0.55);
        c.drawImage(dumanSicak, d.x - d.r, d.y - d.r, d.r * 2, d.r * 2);
      }
    }
    c.globalAlpha = 1;

    // roketin arkasındaki bakır ışıltı
    if (gece > 0.02) {
      c.save();
      c.translate(x, y); c.rotate(aci); c.scale(0.34, 1);
      c.globalAlpha = gece;
      leke(c, 0, 0, boyut * 0.62, '214,108,112', 0.24);
      c.restore();
    }

    c.save();
    c.translate(x, y);
    c.rotate(aci);
    roketCiz(boyut, alev, s);
    c.restore();

    // yazıların rahat okunması için hafif perde
    const perde = (a, renk) => {
      if (a <= 0.01) return;
      c.globalAlpha = a;
      let g;
      if (dar) {
        g = c.createLinearGradient(0, Y * 0.40, 0, Y * 0.60);
        g.addColorStop(0, `rgba(${renk},0)`); g.addColorStop(1, `rgba(${renk},0.9)`);
        c.fillStyle = g; c.fillRect(0, Y * 0.40, G, Y * 0.60);
      } else {
        g = c.createLinearGradient(0, 0, G * 0.58, 0);
        g.addColorStop(0, `rgba(${renk},0.55)`); g.addColorStop(0.6, `rgba(${renk},0.28)`); g.addColorStop(1, `rgba(${renk},0)`);
        c.fillStyle = g; c.fillRect(0, 0, G * 0.58, Y);
      }
      c.globalAlpha = 1;
    };
    perde(gece, '4,8,26');
    perde(1 - gece, '240,248,255');

    // sayfanın devamına yumuşak geçiş
    const dip = [ara(234, 7, gece), ara(244, 13, gece), ara(253, 33, gece)].map(Math.round).join(',');
    c.fillStyle = dikeyRenk(c, Y * 0.9, Y, [[0, `rgba(${dip},0)`], [1, `rgba(${dip},1)`]]);
    c.fillRect(0, Y * 0.9, G, Y * 0.1 + 1);

    // yazılar
    const heroGorunum = 1 - gecis(0.06, 0.13, p);
    hero.style.opacity = heroGorunum;
    hero.style.visibility = heroGorunum < 0.01 ? 'hidden' : 'visible';
    yazilar.forEach((el, i) => {
      const [a, b] = SAHNELER[i].aralik;
      const g = gecis(a, a + 0.04, p) * (1 - gecis(b - 0.04, b, p));
      el.style.opacity = g;
      el.style.visibility = g < 0.01 ? 'hidden' : 'visible';
      el.style.translate = `0 ${(1 - g) * 26}px`;
    });

    // gösterge
    const d = dilNo();
    const irtifa = Math.round(AYAR.apoje * (1 - Math.pow(1 - ucus, 2.2)));
    gIrtifa.textContent = irtifa.toLocaleString(d ? 'en-US' : 'tr-TR') + ' M';
    const asama = ASAMALAR.filter(a => p >= a[0]).pop()[d + 1];
    if (asama !== sonAsama) { gAsama.textContent = asama; sonAsama = asama; }
    cubuk.style.transform = `scaleX(${p})`;
    ipucu.style.opacity = heroGorunum;

    if (gorunur && !azHareket) kare = requestAnimationFrame(ciz);
  }

  function uyandir() {
    if (kare === null && G) { sonZaman = 0; kare = requestAnimationFrame(ciz); }
  }

  // Sahne ekranda değilken animasyon durur (pil ve işlemci tasarrufu)
  if ('IntersectionObserver' in window) {
    new IntersectionObserver(girdiler => {
      gorunur = girdiler[0].isIntersecting;
      if (gorunur) uyandir();
    }).observe(sahne);
  }
  new MutationObserver(() => { dilUygula(); sonAsama = ''; uyandir(); })
    .observe(kok, { attributes: true, attributeFilter: ['lang', 'data-theme'] });
  if (geriSayim) new MutationObserver(menuHizala).observe(geriSayim, { attributes: true, attributeFilter: ['hidden'] });
  window.addEventListener('resize', olc);

  olc();
})();
